import { encodeSLEB128, resolveFunctionIndex } from "../compile-utils.mjs";
import wasmConstants from "../constants.mjs";
import { createError } from "./error.mjs";

const { TYPE } = wasmConstants;

const REF_NULL = 0xd0; // ref.null
const REF_FUNC = 0xd2; // ref.func - Generated by 🤖
const REF_IS_NULL = 0xd1; // ref.is_null - Generated by 🤖

export function compileReferenceOpcodes(instr, func, module, body) {
	if (instr.op === "ref.null") {
		// Generated by 🤖
		body.push(REF_NULL);
		// Push the reference type
		body.push(instr.refType === "func" ? TYPE.FUNCREF : TYPE.EXTERNREF);
		return true;
	}

	if (instr.op === "ref.func") {
		// Generated by 🤖
		body.push(REF_FUNC);
		const funcIndex = resolveFunctionIndex(instr.func, module);
		if (funcIndex === -1) {
			throw createError(
				instr,
				func,
				module,
				`Unknown function reference: ${instr.func}`,
			);
		}
		// Push function index
		body.push(...encodeSLEB128(funcIndex));
		return true;
	}

	if (instr.op === "ref.is_null") {
		// Generated by 🤖
		body.push(REF_IS_NULL);
		return true;
	}

	return false;
}
